from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    separator_rows = [
        r for r in range(h) if len(set(grid[r])) == 1
    ]
    separator_cols = [
        c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1
    ]

    def ranges(size, separators):
        result = []
        start = 0
        for sep in separators + [size]:
            if start < sep:
                result.append((start, sep))
            start = sep + 1
        return result

    row_blocks = ranges(h, separator_rows)
    col_blocks = ranges(w, separator_cols)

    separator_colors = {
        grid[r][0] for r in separator_rows
    } | {
        grid[0][c] for c in separator_cols
    }

    counts = Counter(
        grid[r][c]
        for r0, r1 in row_blocks
        for c0, c1 in col_blocks
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] != 5 and grid[r][c] not in separator_colors
    )
    background = counts.most_common(1)[0][0]

    return [
        [
            1 if sum(grid[r][c] == 5
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_blocks
        ]
        for r0, r1 in row_blocks
    ]
